 */
import { expect, test } from '@playwright/test';

test("功能覆盖 memory", async ({ page }) => {
  const consoleErrors = [];
  const httpErrors = [];
  page.on('console', (msg) => {
    if (msg.type() === 'error') consoleErrors.push(msg.text());
  });
  page.on('response', (response) => {
    if (response.status() >= 400) httpErrors.push(response.status() + ' ' + response.url());
  });
  await page.goto(entryUrl());
  await page.waitForLoadState("load");
  expect(consoleErrors, "console-no-errors").toEqual([]);
  expect(httpErrors, "network-no-http-errors").toEqual([]);
});

function entryUrl() {
  const base = String(process.env["AAFE_E2E_BASE_URL"] ?? '').replace(/\/+$/, '');
  const entryPath = "/.ai-agent/memory";
  if (/^https?:\/\//i.test(entryPath)) return entryPath;
  return base + entryPath;
}

